// work.feed.list — E5 AC4: a project's feed with the source on every item. Generated by `pnpm gen:query`;
// guard case kept, acceptance cases added.
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { aStaffActor } from '@ocs/testing';
import { Forbidden } from '../../kernel/index.ts';
import { addComment } from '../commands/add-comment.ts';
import { createAction } from '../commands/create-action.ts';
import { recordVisit } from '../commands/record-visit.ts';
import { projectFeed } from '../queries/project-feed.ts';
import { openWorkWorld, type WorkWorld } from './fixture.ts';

const pm = aStaffActor({ roles: ['pm'] });
const finance = aStaffActor({ roles: ['finance'] });
const nobody = aStaffActor({ roles: ['admin'] });
// One second per command, so the order of the feed is the order things happened.
let tick = Date.parse('2026-11-02T08:00:00Z');
const clock = () => new Date((tick += 1000));
let w: WorkWorld;

beforeAll(async () => {
  w = await openWorkWorld({ clock });
  w.t.grant(
    pm,
    createAction.permission,
    addComment.permission,
    recordVisit.permission,
    projectFeed.permission,
  );
  w.t.grant(finance, projectFeed.permission);
  await w.t.kernel.execute(
    recordVisit,
    pm,
    {
      siteId: w.siteId,
      type: 'site_survey',
      visitDate: '2026-11-02',
      attendees: [{ name: 'Person A', side: 'vv' }],
      summary: 'Survey done',
      coverage: { done: 4, total: 4 },
      minutesRef: 'Action Record 0001',
      actions: [{ title: 'Send the survey photos', owner: { userId: pm.id }, due: '2026-11-04' }],
    },
    'test',
  );
  await w.t.kernel.execute(
    addComment,
    pm,
    {
      siteId: w.siteId,
      body: 'Client asked for a second camera at the exit',
      source: { kind: 'mail', ref: 'Message 0001' },
    },
    'test',
  );
  await w.t.kernel.execute(
    createAction,
    pm,
    {
      siteId: w.siteId,
      title: 'Quote the extra camera',
      owner: { name: 'Sales A' },
      due: '2026-11-06',
      source: { kind: 'comment' },
    },
    'test',
  );
});

afterAll(async () => {
  await w.close();
});

describe('work.feed.list', () => {
  it('refuses an actor without the permission', async () => {
    await expect(w.t.kernel.read(projectFeed, nobody, { siteId: w.siteId })).rejects.toBeInstanceOf(
      Forbidden,
    );
  });

  it('merges actions, comments and visits newest first, each with its source (E5 AC4)', async () => {
    const feed = await w.t.kernel.read(projectFeed, finance, { siteId: w.siteId });
    expect(feed.map((f) => [f.kind, f.text, f.source.kind, f.source.ref])).toEqual([
      ['action', 'Quote the extra camera', 'comment', null],
      ['comment', 'Client asked for a second camera at the exit', 'mail', 'Message 0001'],
      ['action', 'Send the survey photos', 'visit', expect.any(String)],
      ['visit', 'Survey done', 'visit', 'Action Record 0001'],
    ]);
    expect(feed[3]?.detail).toMatchObject({ type: 'site_survey', coverage: '4 of 4' });
  });

  it('pages with "before" and "limit"', async () => {
    const first = await w.t.kernel.read(projectFeed, finance, { siteId: w.siteId, limit: 2 });
    expect(first).toHaveLength(2);
    const rest = await w.t.kernel.read(projectFeed, finance, { siteId: w.siteId, before: first[1]?.at });
    expect(rest.map((f) => f.kind)).toEqual(['action', 'visit']);
  });
});
